import { CommerceStorefront } from "@/components/CommerceStorefront";

export default function Page() {
  return <CommerceStorefront />;
}

"use client";

import { useMemo, useState } from "react";
import { applyCartMutation, removeCartRecord, transitionCartRecord } from "@/lib/cart-engine";

const initialRecords = [
  {
    "id": "ecommerce-1",
    "label": "Launch Kit",
    "value": "$79",
    "status": "In stock",
    "meta": "Product filters"
  },
  {
    "id": "ecommerce-2",
    "label": "Founder Bundle",
    "value": "$149",
    "status": "Best seller",
    "meta": "Cart drawer",
    "parentId": "ecommerce-1"
  },
  {
    "id": "ecommerce-3",
    "label": "Ops Template",
    "value": "$39",
    "status": "Low stock",
    "meta": "Checkout form",
    "parentId": "ecommerce-1"
  }
];
const views = ["Storefront","Products","Cart","Checkout"];
const transitions = ["Cart","Review","Paid","Fulfilled"];

export function CommerceStorefront({ initialView = views[0] }: { initialView?: string }) {
  const [view, setView] = useState(initialView);
  const [records, setRecords] = useState(initialRecords);
  const [input, setInput] = useState("");
  const [events, setEvents] = useState<string[]>(["CartLoom ready"]);
  const visible = useMemo(() => records.filter((record) => view === views[0] || record.status.toLowerCase().includes(view.toLowerCase()) || record.meta.toLowerCase().includes(view.toLowerCase())), [records, view]);
  function submit() {
    const next = applyCartMutation(records, { label: input || "Checkout", value: "New", status: "Created" });
    setRecords(next.records);
    setEvents((current) => [next.event, ...current]);
    setInput("");
  }
  function advance(id: string) {
    const next = transitionCartRecord(records, id, transitions);
    setRecords(next.records);
    setEvents((current) => [next.event, ...current]);
  }
  function remove(id: string) {
    const next = removeCartRecord(records, id);
    setRecords(next.records);
    setEvents((current) => [next.event, ...current]);
  }
  return (
    <main className="app">
      <header className="top"><div className="wrap" style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"center"}}><strong>CartLoom</strong><nav style={{display:"flex",gap:8,overflowX:"auto"}}>{views.map((item) => <button key={item} onClick={() => setView(item)} className="primary" style={{background:item===view?"var(--primary)":"#e2e8f0",color:item===view?"white":"#0f172a"}}>{item}</button>)}</nav></div></header>
      <section className="wrap hero">
        <div className="panel">
          <p style={{fontWeight:900,textTransform:"uppercase",letterSpacing:".16em",fontSize:12,color:"var(--primary)"}}>ecommerce</p>
          <h1 style={{fontSize:48,lineHeight:1,margin:"10px 0"}}>CartLoom</h1>
          <p style={{lineHeight:1.7,color:"#475569"}}>Build an ecommerce store with products, cart items, orders, checkout, and inventory controls.</p>
          <div className="catalog-grid" style={{marginTop:18}}>{visible.map((record) => <article key={record.id || record.label} className="card"><strong>{record.label}</strong><p style={{fontSize:28,fontWeight:850,margin:"8px 0"}}>{record.value}</p><span>{record.status}</span><div style={{display:"flex",gap:8,marginTop:12}}><button data-action="transition" onClick={() => advance(record.id)} className="primary" style={{padding:"8px 10px"}}>Checkout</button><button data-action="delete" onClick={() => remove(record.id)} className="primary" style={{padding:"8px 10px",background:"#fee2e2",color:"#991b1b"}}>Remove item</button></div></article>)}</div>
        </div>
        <aside className="panel">
          <h2>Checkout</h2>
          <p>Creates a pending order</p>
          <textarea value={input} onChange={(event) => setInput(event.target.value)} placeholder="Email, Shipping ZIP, Payment note" style={{width:"100%",minHeight:110,border:"1px solid #cbd5e1",borderRadius:12,padding:12}} />
          <button onClick={submit} className="primary" style={{width:"100%",marginTop:10}}>add to cart</button>
          <div style={{display:"grid",gap:8,marginTop:16}}>{events.map((event) => <div key={event} className="card">{event}</div>)}</div>
        </aside>
      </section>
    </main>
  );
}

export const interactionMap = [
  {
    "label": "Add to cart",
    "type": "create",
    "target": "CartItem",
    "result": "Adds product to cart and updates total"
  },
  {
    "label": "Checkout",
    "type": "transition",
    "target": "Order",
    "result": "Moves Cart -> Review -> Paid -> Fulfilled"
  },
  {
    "label": "Remove item",
    "type": "delete",
    "target": "CartItem",
    "result": "Removes item and recalculates total"
  }
] as const;
export const relationshipMap = [
  {
    "from": "Product",
    "to": "CartItem",
    "type": "one-to-many",
    "via": "productId"
  },
  {
    "from": "Order",
    "to": "CartItem",
    "type": "one-to-many",
    "via": "orderId"
  }
] as const;

export function validateCartRelationships(record: { parentId?: string }, existingIds: string[]) {
  if (!relationshipMap.length) throw new Error("Generated app requires relational data models.");
  return !record.parentId || existingIds.includes(record.parentId);
}

